def discounted(price, percent):
    """Return price after a percentage discount, rounded to 2 places."""
    return round(price * (1 - percent / 100), 2)

def final_total(prices, percent):
    """Return the sum of the discounted prices, rounded to 2 places."""
    total = 0
    for price in prices:
        total += discounted(price, percent)
    return round(total, 2)

print(final_total([19.99, 5.5, 100], 10))
print(final_total([], 25))

def clean_words(text):
    result = []
    for word in text.lower().split():
        if word.isalpha():
            result.append(word)
    return result

def count_words(words):
    counts = {}
    for word in words:
        counts[word] = counts.get(word, 0) + 1
    return counts

words = clean_words("The cat and the dog and THE bird 42")
counts = count_words(words)
print(words)
print(counts)
best = None
for word, n in counts.items():
    if best is None or n > best[1]:
        best = (word, n)
print(best)
